from collections import defaultdict
class Solution:
    def maxRectangleArea(self, xCoord: List[int], yCoord: List[int]) -> int:
        pts = sorted(zip(xCoord, yCoord))
        last = {}
        ans = -1
        i, n = 0, len(pts)
        while i < n:
            x = pts[i][0]
            col = []
            while i < n and pts[i][0] == x:
                col.append(pts[i][1]); i += 1
            m = len(col)
            for a in range(m):
                for b in range(a + 1, m):
                    key = (col[a], col[b])
                    if key in last:
                        area = (x - last[key]) * (col[b] - col[a])
                        if area > ans:
                            ans = area
            for a in range(m):
                for b in range(a + 1, m):
                    key = (col[a], col[b])
                    if b == a + 1:
                        last[key] = x
                    else:
                        last.pop(key, None)
        return ans

