class Solution {
public:
    int maxRectangleArea(vector<int>& xCoord, vector<int>& yCoord) {
        int n = xCoord.size();
        vector<pair<int,int>> pts(n);
        for (int i = 0; i < n; i++) pts[i] = {xCoord[i], yCoord[i]};
        sort(pts.begin(), pts.end());
        map<pair<int,int>, int> last;
        long long ans = -1;
        int i = 0;
        while (i < n) {
            int x = pts[i].first;
            vector<int> col;
            while (i < n && pts[i].first == x) { col.push_back(pts[i].second); i++; }
            int m = col.size();
            for (int a = 0; a < m; a++)
                for (int b = a + 1; b < m; b++) {
                    auto key = make_pair(col[a], col[b]);
                    auto it = last.find(key);
                    if (it != last.end())
                        ans = max(ans, (long long)(x - it->second) * (col[b] - col[a]));
                }
            for (int a = 0; a < m; a++)
                for (int b = a + 1; b < m; b++) {
                    auto key = make_pair(col[a], col[b]);
                    if (b == a + 1) last[key] = x;
                    else last.erase(key);
                }
        }
        return (int)ans;
    }
};

