class Solution {
    public int maxRectangleArea(int[] xCoord, int[] yCoord) {
        int n = xCoord.length;
        int[][] pts = new int[n][2];
        for (int i = 0; i < n; i++) { pts[i][0] = xCoord[i]; pts[i][1] = yCoord[i]; }
        Arrays.sort(pts, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        Map<Long, Integer> last = new HashMap<>();
        long ans = -1;
        int i = 0;
        while (i < n) {
            int x = pts[i][0];
            List<Integer> col = new ArrayList<>();
            while (i < n && pts[i][0] == x) { col.add(pts[i][1]); i++; }
            int m = col.size();
            for (int a = 0; a < m; a++)
                for (int b = a + 1; b < m; b++) {
                    long key = (long) col.get(a) * 100000001L + col.get(b);
                    Integer px = last.get(key);
                    if (px != null)
                        ans = Math.max(ans, (long)(x - px) * (col.get(b) - col.get(a)));
                }
            for (int a = 0; a < m; a++)
                for (int b = a + 1; b < m; b++) {
                    long key = (long) col.get(a) * 100000001L + col.get(b);
                    if (b == a + 1) last.put(key, x);
                    else last.remove(key);
                }
        }
        return (int) ans;
    }
}

