var maxRectangleArea = function(xCoord, yCoord) {
    const n = xCoord.length;
    const pts = [];
    for (let i = 0; i < n; i++) pts.push([xCoord[i], yCoord[i]]);
    pts.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    const last = new Map();
    let ans = -1, i = 0;
    while (i < n) {
        const x = pts[i][0];
        const col = [];
        while (i < n && pts[i][0] === x) { col.push(pts[i][1]); i++; }
        const m = col.length;
        for (let a = 0; a < m; a++)
            for (let b = a + 1; b < m; b++) {
                const key = col[a] * 1e8 + col[b];
                if (last.has(key)) {
                    const area = (x - last.get(key)) * (col[b] - col[a]);
                    if (area > ans) ans = area;
                }
            }
        for (let a = 0; a < m; a++)
            for (let b = a + 1; b < m; b++) {
                const key = col[a] * 1e8 + col[b];
                if (b === a + 1) last.set(key, x);
                else last.delete(key);
            }
    }
    return ans;
};

