class Solution {
public:
    int maxRectangleArea(vector<int>& xCoord, vector<int>& yCoord) {
        int n = xCoord.size();
        set<pair<int,int>> S;
        vector<int> xs, ys;
        for (int i = 0; i < n; i++) {
            S.insert({xCoord[i], yCoord[i]});
            xs.push_back(xCoord[i]); ys.push_back(yCoord[i]);
        }
        sort(xs.begin()); xs.erase(unique(xs.begin(), xs.end()), xs.end());
        sort(ys.begin()); ys.erase(unique(ys.begin(), ys.end()), ys.end());
        long long ans = -1;
        for (size_t i = 0; i < xs.size(); i++)
            for (size_t j = i + 1; j < xs.size(); j++)
                for (size_t a = 0; a < ys.size(); a++)
                    for (size_t b = a + 1; b < ys.size(); b++) {
                        int x1 = xs[i], x2 = xs[j], y1 = ys[a], y2 = ys[b];
                        bool ok = S.count({x1,y1}) && S.count({x1,y2}) && S.count({x2,y1}) && S.count({x2,y2});
                        if (!ok) continue;
                        for (int k = 0; k < n && ok; k++)
                            if (x1 <= xCoord[k] && xCoord[k] <= x2 && y1 <= yCoord[k] && yCoord[k] <= y2) ok = false;
                        if (ok) ans = max(ans, (long long)(x2-x1)*(y2-y1));
                    }
        return (int)ans;
    }
};

